//! `sermofur_core::store` against the script that the .NET `SqliteStore` played
//! (`rust/tests/golden/store.json`, regenerated by `rust/tools/store-oracle`): the answer of
//! each step, then the rows of every table.

use std::collections::HashSet;
use std::path::{Path, PathBuf};

use rusqlite::Connection;
use serde::Serialize;
use serde_json::{Value, json};
use sermofur_core::error::{Result, SermofurError};
use sermofur_core::format::parse_json_text;
use sermofur_core::records::*;
use sermofur_core::scope_policy::validate_tree;
use sermofur_core::store::Store;
use uuid::Uuid;

struct Scratch(PathBuf);

impl Drop for Scratch {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.0);
    }
}

fn id(n: u32) -> Uuid {
    Uuid::parse_str(&format!("00000000-0000-4000-8000-{n:012}")).expect("GUID")
}

fn provenance(origin: ActorKind, actor: &str) -> Provenance {
    Provenance {
        origin,
        actor: Some(actor.to_owned()),
        timestamp: parse_json_text("2026-03-04T05:06:07+01:00", |_| 0).expect("date"),
    }
}

fn record(n: u32, scope: &str, kind: RecordKind, content: String, p: Provenance) -> MemoryRecord {
    MemoryRecord {
        id: id(n),
        scope_id: Some(scope.to_owned()),
        kind,
        status: KnowledgeStatus::Active,
        revision: 1,
        content_json: Some(content),
        provenance: Some(p),
    }
}

fn claim(n: u32, scope: &str, text: &str, p: Provenance) -> MemoryRecord {
    let content = ClaimContent {
        text: Some(text.to_owned()),
        category: MemoryCategory::Semantic,
        volatility: Volatility::Stable,
        last_verified: None,
        review_after: None,
    };
    record(
        n,
        scope,
        RecordKind::Claim,
        write(&content).expect("json"),
        p,
    )
}

fn evidence(n: u32, scope: &str, claim: Uuid) -> MemoryRecord {
    let content = EvidenceContent {
        claim_id: claim,
        kind: EvidenceKind::SourceCode,
        reference: Some("src/a.cs".to_owned()),
        lineage_id: Some("lineage".to_owned()),
        relation: EvidenceRelation::Supports,
        source_id: None,
        source_hash: None,
    };
    let p = provenance(ActorKind::User, "john");
    record(
        n,
        scope,
        RecordKind::Evidence,
        write(&content).expect("json"),
        p,
    )
}

fn retex(n: u32, scope: &str) -> MemoryRecord {
    let content = RetexContent {
        event: Some("Déploiement raté".to_owned()),
        impact: Some("Service coupé".to_owned()),
        next_action: Some("Ajouter un test".to_owned()),
    };
    let p = provenance(ActorKind::User, "john");
    record(
        n,
        scope,
        RecordKind::Retex,
        write(&content).expect("json"),
        p,
    )
}

fn scope(id: &str, kind: ScopeKind, parent: &str, path: &str) -> Scope {
    Scope {
        id: id.to_owned(),
        kind,
        parent_id: Some(parent.to_owned()),
        relative_path: Some(path.to_owned()),
    }
}

/// The normalization of the oracle, in its order: line breaks, root, backslashes, then the
/// top-level `"timestamp": "..."` values.
fn show(text: &str, root: &Path) -> String {
    let root = root.to_str().expect("UTF-8");
    let text = text
        .replace("\r\n", "\n")
        .replace(root, "<root>")
        .replace('\\', "/");
    let key = "\"timestamp\": \"";
    let mut out = String::new();
    let mut rest = text.as_str();
    while let Some(found) = rest.find(key) {
        out.push_str(&rest[..found + key.len()]);
        let after = &rest[found + key.len()..];
        let end = after.find('"').expect("closing quote");
        out.push_str("<date>");
        rest = &after[end..];
    }
    out.push_str(rest);
    out
}

/// Equality once the line breaks escaped inside nested JSON are made one: .NET writes `\r\n`
/// on Windows and `\n` elsewhere, shown `/r/n` and `/n` once backslashes become `/`.
/// At every depth of nesting: k slashes, `r`, k slashes, `n` become k slashes, `n`.
fn same(a: &Value, b: &Value) -> bool {
    fn collapse(text: &str) -> String {
        let chars: Vec<char> = text.chars().collect();
        let mut out = String::with_capacity(text.len());
        let mut i = 0;
        while i < chars.len() {
            let run = chars[i..].iter().take_while(|c| **c == '/').count();
            let tail = i + run;
            let crlf = run > 0
                && chars.get(tail) == Some(&'r')
                && chars
                    .get(tail + 1..tail + 1 + run)
                    .is_some_and(|s| s.iter().all(|c| *c == '/'))
                && chars.get(tail + 1 + run) == Some(&'n');
            if crlf {
                i = tail + 1;
            } else {
                out.push(chars[i]);
                i += 1;
            }
        }
        out
    }
    collapse(&a.to_string()) == collapse(&b.to_string())
}

fn outcome<T: Serialize>(step: &str, result: Result<Option<T>>, root: &Path) -> Value {
    match result {
        Ok(None) => json!({ "step": step, "result": null }),
        Ok(Some(value)) => {
            json!({ "step": step, "result": show(&write(&value).expect("json"), root) })
        }
        Err(SermofurError { code, .. }) if code == "storage_error" || code == "storage_busy" => {
            json!({ "step": step, "code": code })
        }
        Err(e) => {
            json!({ "step": step, "code": e.code, "message": show(&e.message, root), "exitCode": e.exit_code })
        }
    }
}

fn scopes_json(store: &Store) -> Result<Option<Vec<Scope>>> {
    store
        .read_scopes()?
        .iter()
        .map(|s| s.to_scope())
        .collect::<Result<Vec<_>>>()
        .map(Some)
}

#[test]
fn the_store_answers_like_the_dotnet_store() {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../../tests/golden/store.json");
    let golden: Value =
        serde_json::from_str(&std::fs::read_to_string(path).expect("golden file")).expect("JSON");
    let scratch =
        Scratch(std::env::temp_dir().join(format!("sermofur-store-{}", Uuid::new_v4().simple())));
    let root = scratch.0.clone();
    std::fs::create_dir_all(root.join(".sermofur")).expect("marker");
    let instance = Uuid::parse_str("11111111-2222-4333-8444-555555555555").expect("GUID");
    let database = root.join(".sermofur").join("memory.db");
    sermofur_core::schema::create_database(&database, instance).expect("created");
    let user = provenance(ActorKind::User, "john");
    let llm = provenance(ActorKind::Llm, "claude");
    let set = |ids: &[&str]| {
        ids.iter()
            .map(|s| (*s).to_owned())
            .collect::<HashSet<String>>()
    };
    let all = set(&["workspace", "acme", "web"]);
    let acme = set(&["workspace", "acme"]);
    let none = HashSet::new();
    let mut steps: Vec<Value> = Vec::new();
    let r = &root;
    {
        let mut store = Store::open(&root, instance, false).expect("opened");
        steps.push(outcome("scopes_initial", scopes_json(&store), r));
        let add =
            |store: &mut Store, s: Scope| store.add_scope(&s, |_| Ok(())).map(|()| None::<()>);
        steps.push(outcome(
            "add_client",
            add(
                &mut store,
                scope("acme", ScopeKind::Client, "workspace", "acme"),
            ),
            r,
        ));
        steps.push(outcome(
            "add_project",
            add(
                &mut store,
                scope("web", ScopeKind::Project, "acme", "acme/web"),
            ),
            r,
        ));
        steps.push(outcome(
            "add_repository_under_workspace",
            add(
                &mut store,
                scope("repo", ScopeKind::Repository, "workspace", "repo"),
            ),
            r,
        ));
        let refused = store
            .add_scope(
                &scope("other", ScopeKind::Client, "workspace", "other"),
                |_| {
                    Err(SermofurError::new(
                        "scope_conflict",
                        "Refused by the caller.",
                        4,
                    ))
                },
            )
            .map(|()| None::<()>);
        steps.push(outcome("add_refused_by_precondition", refused, r));
        steps.push(outcome(
            "add_duplicate",
            add(
                &mut store,
                scope("acme", ScopeKind::Client, "workspace", "acme2"),
            ),
            r,
        ));
        steps.push(outcome("scopes_after", scopes_json(&store), r));
        let mut create = |name: &str, candidate: MemoryRecord, steps: &mut Vec<Value>| {
            steps.push(outcome(name, store.create_record(&candidate).map(Some), r));
        };
        create(
            "create_claim_workspace",
            claim(1, "workspace", "Le café est noir & <fort>", user.clone()),
            &mut steps,
        );
        create(
            "create_claim_acme",
            claim(2, "acme", "La facture part le 5", llm.clone()),
            &mut steps,
        );
        create("create_retex_web", retex(3, "web"), &mut steps);
        create(
            "create_evidence_acme",
            evidence(4, "acme", id(2)),
            &mut steps,
        );
        create(
            "create_evidence_other_scope",
            evidence(5, "workspace", id(2)),
            &mut steps,
        );
        create(
            "create_evidence_unknown_claim",
            evidence(6, "acme", id(99)),
            &mut steps,
        );
        create(
            "create_evidence_on_retex",
            evidence(7, "web", id(3)),
            &mut steps,
        );
        create(
            "create_duplicate_id",
            claim(1, "workspace", "Autre", user.clone()),
            &mut steps,
        );
        create(
            "create_unknown_scope",
            claim(8, "nowhere", "x", user.clone()),
            &mut steps,
        );
        steps.push(outcome(
            "read_all",
            store.read_records(&all, None).map(Some),
            r,
        ));
        steps.push(outcome(
            "read_acme_claims",
            store.read_records(&acme, Some(RecordKind::Claim)).map(Some),
            r,
        ));
        steps.push(outcome(
            "read_none",
            store.read_records(&none, None).map(Some),
            r,
        ));
        steps.push(outcome("find_visible", store.find_record(id(2), &acme), r));
        steps.push(outcome(
            "find_invisible",
            store.find_record(id(3), &acme),
            r,
        ));
        steps.push(outcome(
            "history_claim",
            store.read_history(id(2), &acme).map(Some),
            r,
        ));
        steps.push(outcome(
            "history_invisible",
            store.read_history(id(3), &acme).map(Some),
            r,
        ));
        let mut invalidate =
            |name: &str, n: u32, scope: &str, reason: &str, steps: &mut Vec<Value>| {
                steps.push(outcome(
                    name,
                    store
                        .invalidate_record(id(n), scope, reason, "john")
                        .map(Some),
                    r,
                ));
            };
        invalidate("invalidate", 2, "acme", "Obsolète", &mut steps);
        invalidate("invalidate_again", 2, "acme", "Encore", &mut steps);
        invalidate("invalidate_other_scope", 1, "acme", "x", &mut steps);
        invalidate("invalidate_retex", 3, "web", "x", &mut steps);
        invalidate("invalidate_unknown", 98, "acme", "x", &mut steps);
        steps.push(outcome(
            "history_after",
            store.read_history(id(2), &acme).map(Some),
            r,
        ));
    }
    {
        let raw = Connection::open(&database).expect("raw");
        raw.execute("INSERT INTO scopes VALUES('odd','7','workspace',NULL)", [])
            .expect("insert");
    }
    {
        let store = Store::open(&root, instance, false).expect("opened");
        steps.push(outcome("scopes_numeric_kind", scopes_json(&store), r));
        let validated = store
            .read_scopes()
            .and_then(|scopes| validate_tree(&scopes))
            .map(|()| None::<()>);
        steps.push(outcome("validate_numeric_kind", validated, r));
    }
    {
        let raw = Connection::open(&database).expect("raw");
        raw.execute("UPDATE scopes SET kind='client' WHERE id='odd'", [])
            .expect("update");
    }
    {
        let store = Store::open(&root, instance, false).expect("opened");
        steps.push(outcome("scopes_lowercase_kind", scopes_json(&store), r));
    }

    let mut mismatches = Vec::new();
    let expected_steps = golden["steps"].as_array().expect("steps");
    assert_eq!(expected_steps.len(), steps.len());
    for (expected, actual) in expected_steps.iter().zip(&steps) {
        // A .NET exception that is not a Sermofur refusal (JsonException, ArgumentException)
        // is invalid_storage_or_path in the CLI, which the port returns directly.
        let mut expected = expected.clone();
        if expected.get("exception").is_some() {
            expected = json!({
                "step": expected["step"],
                "code": "invalid_storage_or_path",
                "message": "Invalid path or data; run doctor.",
                "exitCode": 3,
            });
        }
        if !same(&expected, actual) {
            mismatches.push(format!("step:\n  expected {expected}\n  got      {actual}"));
        }
    }
    let raw = Connection::open(&database).expect("raw");
    for table in golden["tables"].as_array().expect("tables") {
        let sql = table["sql"].as_str().expect("sql");
        let mut statement = raw.prepare(sql).expect("prepared");
        let count = statement.column_count();
        let rows: Vec<Value> = statement
            .query_map([], |row| {
                let mut cells = Vec::new();
                for i in 0..count {
                    let cell = match row.get_ref(i)? {
                        rusqlite::types::ValueRef::Null => Value::Null,
                        rusqlite::types::ValueRef::Integer(n) => json!(n),
                        rusqlite::types::ValueRef::Text(t) => {
                            json!(show(&String::from_utf8_lossy(t), r))
                        }
                        other => json!(format!("{other:?}")),
                    };
                    cells.push(cell);
                }
                Ok(Value::Array(cells))
            })
            .expect("query")
            .collect::<rusqlite::Result<_>>()
            .expect("rows");
        if !same(&Value::Array(rows.clone()), &table["rows"]) {
            mismatches.push(format!(
                "{sql}:\n  expected {}\n  got      {}",
                table["rows"],
                Value::Array(rows)
            ));
        }
    }
    assert!(mismatches.is_empty(), "{}", mismatches.join("\n"));
}

/// A writer that holds the database for longer than the busy timeout (5 s) makes the next
/// write fail with `storage_busy`, as the code 5 or 6 of `SqliteException` in the CLI.
#[test]
fn a_held_write_lock_is_storage_busy() {
    let scratch =
        Scratch(std::env::temp_dir().join(format!("sermofur-busy-{}", Uuid::new_v4().simple())));
    std::fs::create_dir_all(scratch.0.join(".sermofur")).expect("marker");
    let instance = Uuid::new_v4();
    let database = scratch.0.join(".sermofur").join("memory.db");
    sermofur_core::schema::create_database(&database, instance).expect("created");
    let holder = Connection::open(&database).expect("holder");
    holder.execute_batch("BEGIN IMMEDIATE;").expect("lock held");
    let mut store = Store::open(&scratch.0, instance, false).expect("opened");
    let error = store
        .create_record(&claim(
            1,
            "workspace",
            "x",
            provenance(ActorKind::User, "john"),
        ))
        .expect_err("busy");
    assert_eq!((error.code.as_str(), error.exit_code), ("storage_busy", 3));
    holder.execute_batch("ROLLBACK;").expect("released");
}
